WITH metrics AS (SELECT id, started_at, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC, id) AS seq_no FROM sessions) SELECT CASE WHEN seq_no >= 9 THEN 'HIGH' ELSE 'LOW' END AS seq_no_tier, seq_no, APPROX_PERCENTILE(seq_no, ARRAY(0.25, 0.5, 0.75)) AS seq_no_quartiles, MAX(started_at) AS ended_at, APPROX_PERCENTILE(seq_no, 0.95) AS seq_no_p95, ROUND(AVG(seq_no), 2) AS avg_seq_no FROM metrics GROUP BY 1, 2;
